let lang=localStorage.getItem("masaha-language")||"ar",me=null,authMode="login",reportTarget=null,toastTimer,backendOnline=true,knownReportIds=null,lastUnread=null,categories=[],memberOffset=0;
const $=s=>document.querySelector(s), t=k=>T[lang][k]||k, esc=x=>String(x??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
function formatBody(value){return esc(value).replace(/`([^`]+)`/g,"<code>$1</code>").replace(/\*\*([^*]+)\*\*/g,"<strong>$1</strong>").replace(/\*([^*]+)\*/g,"<em>$1</em>").replace(/\n/g,"<br>")}
function applyDisplayPreferences(){const size=localStorage.getItem("masaha-font-size")||"normal",motion=localStorage.getItem("masaha-reduced-motion")==="true";document.documentElement.dataset.fontSize=["normal","large","xlarge"].includes(size)?size:"normal";document.documentElement.dataset.reducedMotion=String(motion);const sizeLabel=size==="xlarge"?"١٫٥×":size==="large"?"١٫٢٥×":"١×";if($("#font-size-status"))$("#font-size-status").textContent=sizeLabel;if($("#motion-status"))$("#motion-status").textContent=t(motion?"motionOn":"motionOff")}function applyTheme(){const saved=localStorage.getItem("masaha-theme")||"light",theme=["light","dark","contrast"].includes(saved)?saved:"light";document.documentElement.dataset.theme=theme}
const localKey="masaha-local-topics",draftKey=()=>`masaha-topic-draft-${me?.id||"guest"}`;let messagePeer=null,messageRefreshTimer=null,installPrompt=null;
function badgeLabel(key){return t(`badge${key.split("_").map(x=>x[0].toUpperCase()+x.slice(1)).join("")}`)}
function categoryName(slug){const c=categories.find(x=>x.slug===slug);return c?(lang==="ar"?c.name_ar:c.name_en):t(slug)}
function categoryOptions(selected=""){return categories.map(c=>`<option value="${esc(c.slug)}" ${c.slug===selected?"selected":""}>${esc(categoryName(c.slug))}</option>`).join("")}
async function loadCategories(){const fallback=[{slug:"programming",name_ar:"البرمجة",name_en:"Programming",description:"أسئلة وتجارب ومشاريع برمجية.",topic_count:0},{slug:"learning",name_ar:"التعلّم",name_en:"Learning",description:"مصادر وتجارب تساعدنا على التعلّم.",topic_count:0},{slug:"general",name_ar:"نقاش عام",name_en:"General",description:"موضوعات وأفكار عامة.",topic_count:0}];try{categories=(await api("/api/categories")).categories}catch{categories=fallback}categories.sort((a,b)=>(Number(b.topic_count)||0)-(Number(a.topic_count)||0)||String(a.slug).localeCompare(String(b.slug)));renderCategories()}
function renderCategories(){const list=$("#categories-list"),filter=$("#category-filter"),keep=filter?.value||"";if(list)list.innerHTML=categories.map(c=>`<div class="category category-card category-${esc(c.slug)}"><a href="#category/${encodeURIComponent(c.slug)}"><span class="category-icon" aria-hidden="true">${({programming:"⌘",learning:"✦",general:"💬"})[c.slug]||"▧"}</span><span class="category-copy"><b>${esc(categoryName(c.slug))}</b><small>${esc(c.description||"")}</small></span><span class="tag">${Number(c.topic_count)||0}</span></a>${me?`<button type="button" class="follow-category" data-follow-category="${esc(c.slug)}">${c.followed_by_me?t("unfollow"):t("follow")}</button>`:""}</div>`).join("");if(filter)filter.innerHTML=`<option value="">${t("allCategories")}</option>${categoryOptions(keep)}`;for(const id of ["topic-form","edit-topic-form"]){const select=document.querySelector(`#${id} select[name=category]`);if(select){const value=select.value;select.innerHTML=categoryOptions(value)}}renderAdminCategories()}
function renderAdminCategories(){const el=$("#admin-categories");if(!el)return;el.innerHTML=categories.map(c=>`<div class="category-admin-row"><span><b>${esc(categoryName(c.slug))}</b><small>${esc(c.slug)} · ${Number(c.topic_count)||0}</small></span>${!["programming","learning","general"].includes(c.slug)?`<button type="button" class="small-button" data-delete-category="${esc(c.slug)}">${t("deleteCategory")}</button>`:""}</div>`).join("")}

function localTopics(){try{return JSON.parse(localStorage.getItem(localKey)||"[]")}catch{return[]}}
function saveLocalTopics(xs){localStorage.setItem(localKey,JSON.stringify(xs))}
function localApi(path,opts={}){const method=(opts.method||"GET").toUpperCase(),body=typeof opts.body==="string"?JSON.parse(opts.body||"{}"):{};let xs=localTopics();if(path.startsWith("/api/members"))return{members:[]};if(path==="/api/me")return{user:null};if(path==="/api/categories")return{categories:[{slug:"programming",name_ar:"البرمجة",name_en:"Programming",description:"",topic_count:0},{slug:"learning",name_ar:"التعلّم",name_en:"Learning",description:"",topic_count:0},{slug:"general",name_ar:"نقاش عام",name_en:"General",description:"",topic_count:0}]};if(path.startsWith("/api/topics?")||path==="/api/topics"){if(method==="GET"){const u=new URL(path,"http://local"),q=(u.searchParams.get("q")||"").toLowerCase(),cat=u.searchParams.get("category")||"",sort=u.searchParams.get("sort")||"newest";let items=xs.filter(x=>(!cat||x.category===cat)&&(!q||(x.title+" "+x.body).toLowerCase().includes(q)));items.sort(sort==="popular"?(a,b)=>(b.likeCount||0)-(a.likeCount||0)||b.createdAt-a.createdAt:sort==="oldest"?(a,b)=>a.createdAt-b.createdAt:(a,b)=>b.createdAt-a.createdAt);const total=items.length,limit=Number(u.searchParams.get("limit")||20),offset=Number(u.searchParams.get("offset")||0);return{topics:items.slice(offset,offset+limit),total}}if(method==="POST"){const x={id:"local-"+Date.now(),title:body.title,body:body.body,category:body.category,tags:String(body.tags||"").split(",").map(a=>a.trim().replace(/^#/,"")).filter(Boolean).slice(0,8),createdAt:Date.now()/1000,user:{id:"local",username:"guest",displayName:lang==="ar"?"زائر":"Guest",avatarUrl:""},commentCount:0,likeCount:0,imageUrl:body.image||"",likedByMe:false,bookmarkedByMe:false,comments:[]};xs.unshift(x);saveLocalTopics(xs);return{id:x.id}}}const m=path.match(/^\/api\/topics\/([^/?]+)(?:\/(comments|like|bookmark))?/);if(m){const x=xs.find(a=>a.id===m[1]);if(!x)throw Error(t("failed"));if(!m[2])return{topic:x,comments:x.comments||[]};if(m[2]==="comments"&&method==="POST"){x.comments=x.comments||[];x.comments.push({id:"local-comment-"+Date.now(),body:body.body,createdAt:Date.now()/1000,user:x.user});x.commentCount=x.comments.length;saveLocalTopics(xs);return{ok:true}}if(m[2]==="like"){x.likedByMe=!x.likedByMe;x.likeCount=Math.max(0,x.likeCount+(x.likedByMe?1:-1));saveLocalTopics(xs);return{ok:true}}if(m[2]==="bookmark"){x.bookmarkedByMe=!x.bookmarkedByMe;saveLocalTopics(xs);return{saved:x.bookmarkedByMe}}}if(path==="/api/bookmarks")return{topics:xs.filter(x=>x.bookmarkedByMe)};if(path.startsWith("/api/notifications"))return{notifications:[],unread:0};throw Error(lang==="ar"?"هذه الميزة تحتاج تشغيل خادم Python.":"This feature requires the Python server.")}
async function api(path,opts={}){if(!backendOnline)return localApi(path,opts);const headers={...(opts.headers||{})};if(!(opts.body instanceof FormData))headers["Content-Type"]="application/json";try{const r=await fetch(path,{...opts,headers,credentials:"same-origin"});let d,validJson=true;try{d=await r.json()}catch{validJson=false}if(!validJson){backendOnline=false;return localApi(path,opts)}if(!r.ok)throw Object.assign(Error(d.error||t("failed")),{data:d});return d}catch(e){if(e instanceof TypeError||e instanceof SyntaxError){backendOnline=false;return localApi(path,opts)}throw e}}
function toast(s){const e=$("#toast");e.textContent=s;e.classList.add("show");clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove("show"),3200)}
function date(s){return new Intl.DateTimeFormat(lang==="ar"?"ar":"en",{dateStyle:"medium",timeStyle:"short"}).format(new Date(s*1000))}
function setLang(){$("#guest-join").hidden=!!me;$("#member-welcome").hidden=!me;$("#welcome-member-title").textContent=me?t("memberWelcomeTitle").replace("{name}",me.displayName):"";$("#sidebar-profile-link").href=me?`#profile/${me.id}`:"#profile/0";document.documentElement.lang=lang;document.documentElement.dir=lang==="ar"?"rtl":"ltr";document.querySelectorAll("[data-t]").forEach(e=>e.textContent=t(e.dataset.t));document.querySelectorAll("[data-t-placeholder]").forEach(e=>e.placeholder=t(e.dataset.tPlaceholder));$("#language").textContent=lang==="ar"?"English":"العربية";$("#profile-link").hidden=!me;$("#settings-open").hidden=!me;$("#notifications-open").hidden=!me;$("#messages-open").hidden=!me;$("#following-link").hidden=!me;$("#notifications-open").setAttribute("aria-label",t("notifications"));$("#theme-toggle").setAttribute("aria-label",t(document.documentElement.dataset.theme==="dark"?"themeDark":document.documentElement.dataset.theme==="contrast"?"themeContrast":"themeLight"));$("#theme-toggle").setAttribute("title",$("#theme-toggle").getAttribute("aria-label"));$("#bookmarks-link").hidden=!me;$("#reports-link").hidden=!(me&&(me.role==="admin"||me.role==="moderator"));$("#admin-dashboard-link").hidden=!(me&&(me.role==="admin"||me.role==="moderator"));$("#backup-tools").hidden=me?.role!=="admin";$("#owner-category-tools").hidden=me?.role!=="admin";$("#login-open").textContent=me?`${me.displayName} · ${t("logout")}`:t("login");$("#menu-account-name").textContent=me?me.displayName:t("guestMenu");$("#menu-account-status").textContent=me?`${me.role==="admin"?t("adminStatus"):t("memberStatus")} · ${me.profileVisibility==="private"?t("privateStatus"):t("publicStatus")}`:t("guestStatus");$("#menu-auth").textContent=me?t("logout"):t("menuLogin");$("#menu-auth").classList.toggle("danger-button",!!me);$("#menu-profile").hidden=!me;$("#menu-messages").hidden=!me;$("#menu-notifications").hidden=!me;$("#menu-settings").hidden=!me;$("#menu-following").hidden=!me;$("#menu-bookmarks").hidden=!me;$("#menu-reports").hidden=!(me&&(me.role==="admin"||me.role==="moderator"));$("#menu-admin").hidden=!(me&&(me.role==="admin"||me.role==="moderator"));$("#menu-admin-tools").hidden=!(me&&(me.role==="admin"||me.role==="moderator"));$("#menu-admin-categories").hidden=me?.role!=="admin";$("#menu-activity").hidden=!me;if(!me){$("#menu-new-replies-count").hidden=true;$("#menu-started-list").replaceChildren();$("#menu-participated-list").replaceChildren();$("#menu-new-replies-list").replaceChildren()}$("#mobile-menu").setAttribute("aria-label",t("menu"));$("#mobile-menu").setAttribute("title",t("menu"));$("#menu-close").setAttribute("aria-label",t("menuClose"));$("#theme-toggle").textContent=document.documentElement.dataset.theme==="dark"?"☀️":document.documentElement.dataset.theme==="contrast"?"◐":"🌙";renderCategories()}
function avatar(user){return user.avatarUrl?`<img class="avatar-img" src="${esc(user.avatarUrl)}" alt="">`:`<span>${esc((user.displayName||"?").slice(0,1))}</span>`}
function card(x){return `<article class="topic ${x.isPinned?"topic-pinned":""}"><div class="avatar">${avatar(x.user)}</div><div class="topic-body">${x.isPinned?`<span class="pin-label">📌 ${t("pinned")}</span>`:""}<a class="topic-title" href="#topic/${x.id}">${esc(x.title)}</a><p>${formatBody(x.body.length>300?x.body.slice(0,300)+"…":x.body)}</p>${x.hasPoll?`<span class="poll-badge">▤ ${t("votes")}</span>`:""}${(x.images|| (x.imageUrl?[x.imageUrl]:[])).map((src,index)=>`<img class="topic-image" src="${esc(src)}" alt="${t("topicImage")} ${index+1}" loading="lazy" decoding="async">`).join("")}${x.tags?.length?`<div class="topic-tags">${x.tags.map(tag=>`<a href="#tag/${encodeURIComponent(tag)}" class="tag-chip">#${esc(tag)}</a>`).join("")}</div>`:""}<div class="meta"><span class="tag">${esc(categoryName(x.category))}</span><a class="profile-link" href="#profile/${x.user.id}">${t("by")} ${esc(x.user.displayName)}</a><span>${date(x.createdAt)}</span><span>💬 ${x.commentCount}</span><span>♥ ${x.likeCount}</span></div><div class="topic-actions"><button class="small-button" data-like="${x.id}">${x.likedByMe?t("unlike"):t("like")} · ${x.likeCount}</button><button class="small-button" data-bookmark="${x.id}">${x.bookmarkedByMe?t("unbookmark"):t("bookmark")}</button><button class="small-button" data-report-type="topic" data-report-id="${x.id}">${t("report")}</button>${me&&me.role==="admin"?`<button class="small-button" data-pin-topic="${x.id}">${x.isPinned?t("unpin"):t("pin")}</button>`:""}${me&&(me.role==="admin"||Number(me.id)===Number(x.user.id))?`<button class="small-button" data-edit-topic="${x.id}">${t("edit")}</button><button class="small-button" data-admin="delete" data-type="topic" data-id="${x.id}">${t("remove")}</button>`:""}</div></div></article>`}
let topicPage=0;const topicPageSize=20;
function loadingState(){return `<div class="loading-state" role="status"><span class="loading-spinner"></span><div class="loading-lines"><i></i><i></i><i></i></div><p>${t("loadingHint")}</p></div>`}
function emptyState(title,hint,action="",label="",icon="✦"){return `<div class="state-card"><span class="state-icon" aria-hidden="true">${icon}</span><h3>${t(title)}</h3><p>${t(hint)}</p>${action?`<button class="cta" data-state-action="${action}">${t(label)}</button>`:""}</div>`}
function topicEmptyState(q="",cat=""){if(q)return emptyState("noSearchResults","noSearchResultsHint","clear","clearFilters","⌕");if(me)return emptyState("noTopics","newTopicHint","new-topic","newTopic","✦");return emptyState("noTopics","newTopicHint","join","join","✦")}
function stateError(error){return `<div class="state-card state-error"><span class="state-icon" aria-hidden="true">⚠️</span><h3>${t("loadFailed")}</h3><p>${esc(error)}</p><button class="cta" data-state-action="retry">${t("tryAgain")}</button></div>`}
async function loadTopics(q="",cat="",sort=$("#sort-filter").value,append=false){const c=$("#content"),more=$("#load-more");if(!append){topicPage=0;c.innerHTML=loadingState()}try{const p=new URLSearchParams();if(q)p.set("q",q);if(cat)p.set("category",cat);if(sort)p.set("sort",sort);const tag=$("#tag-filter")?.value.trim().replace(/^#/ ,"");if(tag)p.set("tag",tag);const range=Number($("#date-filter")?.value||0);if(range)p.set("since",String(Math.floor(Date.now()/1000)-range));p.set("limit",topicPageSize);p.set("offset",topicPage*topicPageSize);const d=await api(`/api/topics?${p}`);const html=d.topics.map(card).join("");if(append)c.insertAdjacentHTML("beforeend",html);else c.innerHTML=html||topicEmptyState(q,cat);more.hidden=(topicPage+1)*topicPageSize>=d.total}catch(e){if(append){topicPage=Math.max(0,topicPage-1);toast(e.message)}else c.innerHTML=stateError(e.message);more.hidden=true}}

async function openTopic(id,commentSort=localStorage.getItem("masaha-comment-sort")||"newest"){localStorage.setItem("masaha-comment-sort",commentSort);$("#load-more").hidden=true;const c=$("#content");c.innerHTML=loadingState();try{const d=await api(`/api/topics/${id}?comments=${encodeURIComponent(commentSort)}`),x=d.topic;$("#view-title").textContent=x.title;document.title=`${x.title} | ${t("brand")}`;c.innerHTML=`<article class="topic"><div class="avatar">${avatar(x.user)}</div><div class="topic-body"><div class="meta">${x.isPinned?`<span class="pin-label">📌 ${t("pinned")}</span>`:""}<span class="tag">${esc(categoryName(x.category))}</span><a class="profile-link" href="#profile/${x.user.id}">${esc(x.user.displayName)}</a><span>${date(x.createdAt)}</span></div><p class="detail-body">${formatBody(x.body)}</p>${(x.images|| (x.imageUrl?[x.imageUrl]:[])).map((src,index)=>`<img class="topic-image" src="${esc(src)}" alt="${t("topicImage")} ${index+1}" loading="lazy" decoding="async">`).join("")}${x.tags?.length?`<div class="topic-tags">${x.tags.map(tag=>`<a href="#tag/${encodeURIComponent(tag)}" class="tag-chip">#${esc(tag)}</a>`).join("")}</div>`:""}${pollMarkup(d.poll,x.id)}<div class="topic-actions"><button class="small-button" data-like="${x.id}">${x.likedByMe?t("unlike"):t("like")} · ${x.likeCount}</button><button class="small-button" data-bookmark="${x.id}">${x.bookmarkedByMe?t("unbookmark"):t("bookmark")}</button><button class="small-button" data-report-type="topic" data-report-id="${x.id}">${t("report")}</button>${me&&me.role==="admin"?`<button class="small-button" data-pin-topic="${x.id}">${x.isPinned?t("unpin"):t("pin")}</button>`:""}</div></div></article><section class="comments"><div class="comments-head"><h3>${d.comments.length} ${t("replies")}</h3><label><span>${t("commentSort")}</span><select data-comments-sort><option value="newest" ${commentSort==="newest"?"selected":""}>${t("sortNewest")}</option><option value="oldest" ${commentSort==="oldest"?"selected":""}>${t("sortOldest")}</option><option value="helpful" ${commentSort==="helpful"?"selected":""}>${t("sortHelpful")}</option></select></label></div>${d.comments.length?d.comments.map(a=>`<article class="comment ${Number(x.bestAnswerId)===Number(a.id)?"best-answer":""} ${a.isPinned?"reply-pinned":""}"><div class="meta">${Number(x.bestAnswerId)===Number(a.id)?`<span class="tag best-answer-label">✓ ${t("bestAnswer")}</span>`:""}<a class="profile-link" href="#profile/${a.user.id}">${esc(a.user.displayName)}</a><span>${date(a.createdAt)}</span></div><p>${esc(a.body)}</p><div class="topic-actions"><button class="small-button" data-quote-reply="${a.id}" data-quote-name="${esc(a.user.displayName)}" data-quote-body="${esc(a.body)}">↩ ${t("quoteReply")}</button>${me&&(Number(me.id)===Number(x.user.id)||me.role==="admin")?`<button class="small-button" data-pin-comment="${x.id}" data-comment-id="${a.id}">${a.isPinned?t("unpinReply"):t("pinReply")}</button>`:""}<button class="small-button" data-report-type="comment" data-report-id="${a.id}">${t("report")}</button>${me&&(Number(me.id)===Number(x.user.id)||me.role==="admin")?`<button class="small-button" data-best-answer="${x.id}" data-comment-id="${a.id}">${Number(x.bestAnswerId)===Number(a.id)?t("bestAnswer"):t("markBestAnswer")}</button>`:""}${me&&(me.role==="admin"||Number(me.id)===Number(a.user.id))?`<button class="small-button" data-edit-comment="${a.id}" data-body="${esc(a.body)}">${t("editReply")}</button><button class="small-button" data-admin="delete" data-type="comment" data-id="${a.id}">${t("deleteReply")}</button>`:""}</div></article>`).join(""):`<p class="muted">${t("noComments")}</p>`}${me||!backendOnline?`<form class="comment-form" id="comment-form"><textarea name="body" maxlength="3000" required placeholder="${t("writeReply")}"></textarea><button class="cta">${t("sendReply")}</button></form>`:`<button class="cta" data-auth="login">${t("login")}</button>`}</section>`;const f=$("#comment-form");if(f)f.onsubmit=async e=>{e.preventDefault();try{await api(`/api/topics/${id}/comments`,{method:"POST",body:JSON.stringify({body:new FormData(f).get("body")})});toast(t("sent"));openTopic(id)}catch(err){toast(err.message)}}}catch(e){c.innerHTML=stateError(e.message)}}
async function openProfile(id){$("#load-more").hidden=true;const c=$("#content");c.innerHTML=loadingState();try{const d=await api(`/api/users/${id}`),u=d.user;$("#view-title").textContent=t("profile");c.innerHTML=`<section class="profile-box">${u.coverUrl?`<img class="profile-cover" src="${esc(u.coverUrl)}" alt="">`:""}<div class="avatar profile-avatar">${avatar(u)}</div><h2>${esc(u.displayName)}</h2><div class="muted">@${esc(u.username)} · ${t("memberSince")} ${date(u.createdAt)}</div><p>${esc(u.bio||t("profileHint"))}</p>${u.website?`<p><a class="profile-website" href="${esc(u.website)}" target="_blank" rel="noopener noreferrer">↗ ${esc(u.website)}</a></p>`:""}${u.interests?.length?`<div class="profile-interests">${u.interests.map(i=>`<span class="tag-chip">${esc(i)}</span>`).join("")}</div>`:""}<div class="profile-stats"><span><b>${u.topicCount||0}</b> ${t("topicCount")}</span><span><b>${u.replyCount||0}</b> ${t("replyCount")}</span><span><b>${u.points||0}</b> ${t("points")}</span><span><b>${u.followerCount||0}</b> ${t("followers")}</span></div>${u.badges?.length?`<div class="member-badges">${u.badges.map(b=>`<span class="badge-chip">🏅 ${esc(badgeLabel(b))}</span>`).join("")}</div>`:""}${me&&Number(me.id)!==Number(u.id)?`<button class="cta" data-message-user="${u.id}" data-message-name="${esc(u.displayName)}">✉ ${t("messageTo")}</button><button class="cta follow-member" data-follow-user="${u.id}">${u.followedByMe?t("unfollow"):t("follow")}</button>`:""}${me&&me.id===u.id?`<form id="cover-form"><label class="text-button">${t("editCover")}<input type="file" name="cover" accept="image/png,image/jpeg,image/webp" hidden></label></form><form id="avatar-form"><label class="text-button">${t("uploadAvatar")}<input type="file" name="avatar" accept="image/png,image/jpeg,image/webp" hidden></label></form><button class="cta" id="edit-profile">${t("editProfile")}</button><button class="small-button" id="profile-settings">${t("settings")}</button><form id="profile-form" class="comment-form" hidden><input name="displayName" minlength="2" maxlength="50" value="${esc(u.displayName)}" required><textarea name="bio" maxlength="500">${esc(u.bio)}</textarea><label class="field"><span>${t("website")}</span><input name="website" type="url" maxlength="240" value="${esc(u.website||"")}" placeholder="https://example.com"></label><label class="field"><span>${t("interests")}</span><input name="interests" maxlength="240" value="${esc((u.interests||[]).join(", "))}"></label><label class="field"><span>${t("profilePrivacy")}</span><select name="profileVisibility"><option value="public" ${u.profileVisibility!=="private"?"selected":""}>${t("publicProfile")}</option><option value="private" ${u.profileVisibility==="private"?"selected":""}>${t("privateProfile")}</option></select></label><button class="cta">${t("save")}</button></form>`:""}</section><div class="profile-tabs" role="tablist"><button type="button" class="active" role="tab" aria-selected="true" data-profile-tab="posts">${t("profilePostsTab")}</button><button type="button" role="tab" aria-selected="false" data-profile-tab="replies">${t("profileRepliesTab")}</button></div><section class="profile-activity" data-profile-panel="posts"><div class="profile-section-head"><span>✦</span><div><h3>${t("posts")}</h3><p>${t("profilePostsHint")}</p></div><b>${d.topics.length}</b></div>${d.topics.length?d.topics.map(card).join(""):emptyState("noTopics","profilePostsHint","","","✦")}</section><section class="profile-activity" data-profile-panel="replies" hidden><div class="profile-section-head"><span>↳</span><div><h3>${t("replyCount")}</h3><p>${t("profileRepliesHint")}</p></div><b>${d.replies?.length||0}</b></div>${d.replies?.length?d.replies.map(r=>`<a class="profile-reply" href="#topic/${r.topic_id}"><b>${esc(r.title)}</b><span>${esc(r.body.slice(0,150))}</span><small>${date(r.created_at)}</small></a>`).join(""):emptyState("noComments","profileRepliesHint","","","↳")}</section>`;document.querySelectorAll("[data-profile-tab]").forEach(tab=>tab.onclick=()=>{document.querySelectorAll("[data-profile-tab]").forEach(x=>{const active=x===tab;x.classList.toggle("active",active);x.setAttribute("aria-selected",String(active))});document.querySelectorAll("[data-profile-panel]").forEach(panel=>panel.hidden=panel.dataset.profilePanel!==tab.dataset.profileTab)});const ps=$("#profile-settings");if(ps)ps.onclick=()=>openSettings();const ed=$("#edit-profile");if(ed)ed.onclick=()=>{$("#profile-form").hidden=false;ed.hidden=true};const f=$("#profile-form");if(f)f.onsubmit=async e=>{e.preventDefault();try{const d=await api("/api/me/profile",{method:"PUT",body:JSON.stringify(Object.fromEntries(new FormData(f)))});me={...me,...d.user};toast(t("profileSaved"));openProfile(id)}catch(err){toast(err.message)}};const cf=$("#cover-form input");if(cf)cf.onchange=async()=>{if(cf.files[0])try{const image=await fileData(cf.files[0]);await api("/api/me/cover",{method:"POST",body:JSON.stringify({image})});openProfile(id)}catch(err){toast(err.message)}};const af=$("#avatar-form input");if(af)af.onchange=async()=>{if(af.files[0])try{const image=await fileData(af.files[0]);const d=await api("/api/me/avatar",{method:"POST",body:JSON.stringify({image})});me.avatarUrl=d.avatarUrl;openProfile(id)}catch(err){toast(err.message)}}}catch(e){c.innerHTML=e.message==="PROFILE_PRIVATE"?emptyState("profilePrivate","profilePrivate"):stateError(e.message)}}
async function loadBookmarks(){$("#load-more").hidden=true;$("#content").innerHTML=loadingState();try{const p=new URLSearchParams({sort:$("#sort-filter").value||"newest"});if($("#search").value)p.set("q",$("#search").value);if($("#category-filter").value)p.set("category",$("#category-filter").value);const d=await api(`/api/bookmarks?${p}`);$("#view-title").textContent=t("bookmarks");$("#content").innerHTML=d.topics.length?d.topics.map(card).join(""):emptyState("noSavedTopics","noSearchResultsHint")}catch(e){$("#content").innerHTML=stateError(e.message)}}
async function loadFollowing(){$("#load-more").hidden=true;$("#view-title").textContent=t("followingFeed");$("#content").innerHTML=loadingState();try{const d=await api("/api/following-feed"),items=d.topics;const draw=()=>{const q=$("#feed-search").value.trim().toLowerCase(),category=$("#feed-category").value,sort=$("#feed-sort").value;let visible=items.filter(x=>(!q||`${x.title} ${x.body} ${x.user.displayName} ${(x.tags||[]).join(" ")}`.toLowerCase().includes(q))&&(!category||x.category===category));if(sort==="popular")visible.sort((a,b)=>Number(b.likeCount||0)-Number(a.likeCount||0)||b.createdAt-a.createdAt);else visible.sort((a,b)=>Number(b.isPinned)-Number(a.isPinned)||b.createdAt-a.createdAt);$("#feed-results").innerHTML=visible.length?visible.map(card).join(""):emptyState("noSearchResults","noSearchResultsHint")};$("#content").innerHTML=`<div class="feed-toolbar"><input id="feed-search" type="search" placeholder="${t("searchPlaceholder")}" aria-label="${t("searchPlaceholder")}"><select id="feed-category" aria-label="${t("categoryLabel")}"><option value="">${t("allCategories")}</option>${categoryOptions()}</select><select id="feed-sort" aria-label="${t("sortNewest")}"><option value="newest">${t("sortNewest")}</option><option value="popular">${t("sortPopular")}</option></select></div><div id="feed-results"></div>`;$("#feed-search").oninput=draw;$("#feed-category").onchange=draw;$("#feed-sort").onchange=draw;draw()}catch(e){$("#content").innerHTML=stateError(e.message)}}
async function loadMembers(q=""){$("#load-more").hidden=true;$("#view-title").textContent=t("membersDirectory");$("#content").innerHTML=loadingState();try{const d=await api(`/api/members?q=${encodeURIComponent(q)}`);const list=d.members.map(u=>`<a class="directory-member" href="#profile/${u.id}"><span class="avatar">${avatar(u)}</span><span><b>${esc(u.displayName)}</b><small>@${esc(u.username)}</small></span><span class="directory-arrow" aria-hidden="true">›</span></a>`).join("");$("#content").innerHTML=`<div class="member-directory"><label class="field"><span>${t("membersSearch")}</span><input id="directory-search" type="search" value="${esc(q)}" autocomplete="off"></label><p class="muted directory-hint">${t("membersSortHint")}</p><div id="directory-results">${list||emptyState("noMembers","membersSearch")}</div></div>`;let timer;$("#directory-search").oninput=e=>{clearTimeout(timer);timer=setTimeout(()=>loadMembers(e.target.value.trim()),260)}}catch(e){$("#content").innerHTML=stateError(e.message)}}
function pollMarkup(poll,topicId){if(!poll)return "";const choices=poll.options.map((option,index)=>{const count=poll.counts[index]||0,percent=poll.total?Math.round(count*100/poll.total):0;return poll.selected===null?`<button class="poll-option" data-vote="${topicId}" data-option="${index}">${esc(option)}</button>`:`<div class="poll-result"><div><span>${esc(option)}</span><b>${percent}% · ${count}</b></div><i style="width:${percent}%"></i></div>`}).join("");return `<section class="poll-box"><h3>${esc(poll.question)}</h3>${choices}<p class="muted">${poll.total} ${t("votes")}</p></section>`}
async function route(){const h=decodeURIComponent(location.hash||"#home"),query=new URLSearchParams(location.search);$("#category-hero").hidden=true;$("#help-section").hidden=true;$("#legal-section").hidden=true;$("#admin-dashboard").hidden=true;if(h==="#privacy"||h==="#terms"){$("#forum-content").hidden=true;$("#reports-section").hidden=true;$("#legal-section").hidden=false;$("#privacy-content").hidden=h==="#terms";$("#terms-content").hidden=h==="#privacy";$("#legal-title").textContent=t(h==="#privacy"?"privacy":"terms");document.title=`${t(h==="#privacy"?"privacy":"terms")} | ${t("brand")}`;return}if(h==="#help"){$("#forum-content").hidden=true;$("#reports-section").hidden=true;$("#help-section").hidden=false;document.title=`${t("help")} | ${t("brand")}`;return}if(h==="#admin"&&me&&(me.role==="admin"||me.role==="moderator")){$("#forum-content").hidden=true;$("#reports-section").hidden=true;$("#admin-dashboard").hidden=false;document.title=`${t("adminDashboard")} | ${t("brand")}`;return drawAdmin()}if(h==="#reports"&&me&&(me.role==="admin"||me.role==="moderator")){$("#forum-content").hidden=true;$("#reports-section").hidden=false;document.title=`${t("reports")} | ${t("brand")}`;return drawAdmin()}$("#forum-content").hidden=false;$("#reports-section").hidden=true;if(query.get("topic"))return openTopic(query.get("topic"));if(h.startsWith("#topic/"))return openTopic(h.split("/")[1]);if(h.startsWith("#profile/"))return openProfile(h.split("/")[1]);if(h==="#members")return loadMembers();if(h==="#bookmarks"&&me)return loadBookmarks();if(h==="#following"&&me)return loadFollowing();if(h.startsWith("#tag/")){return loadTopics(h.slice(5),"")}if(h.startsWith("#category/")){const cat=h.split("/")[1],item=categories.find(x=>x.slug===cat);$("#category-filter").value=cat;$("#category-hero").hidden=false;$("#category-hero-title").textContent=item?categoryName(item.slug):cat;$("#category-hero-description").textContent=item?.description||t("categoryDescriptionFallback");$("#category-hero-icon").textContent=({programming:"⌘",learning:"✦",general:"💬"})[cat]||"▧";$("#view-title").textContent=categoryName(cat);return loadTopics($("#search").value,cat)}$("#category-hero").hidden=true;$("#view-title").textContent=t("latest");if(me)refreshMemberHome();document.title=`${t("brand")} | ${t("latest")}`;$("#category-filter").value="";return loadTopics($("#search").value,"")}
function fileData(file){return new Promise((resolve,reject)=>{if(!file.type.startsWith("image/"))return reject(Error("Choose an image file"));if(file.size>12_000_000)return reject(Error("Image file is too large"));const reader=new FileReader();reader.onerror=reject;reader.onload=()=>{const image=new Image();image.onerror=()=>reject(Error("Image could not be read"));image.onload=()=>{const scale=Math.min(1,1600/image.width,1600/image.height),canvas=document.createElement("canvas");canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));canvas.getContext("2d").drawImage(image,0,0,canvas.width,canvas.height);const encoded=canvas.toDataURL("image/webp",.82),finalImage=encoded.startsWith("data:image/webp")?encoded:canvas.toDataURL("image/jpeg",.82);if(finalImage.length>2_800_000)return reject(Error("OPTIMIZED_IMAGE_TOO_LARGE"));resolve(finalImage)};image.src=reader.result};reader.readAsDataURL(file)})}
function auth(mode="login"){authMode=mode;$("#auth-dialog").showModal();authTabs()}
function authTabs(){const reg=authMode==="register",identifier=$("#auth-form input[name=email]");identifier.type=reg?"email":"text";identifier.autocomplete=reg?"email":"username";$("#auth-email-label").textContent=t(reg?"email":"emailOrUsername");$("#register-tab").classList.toggle("active",reg);$("#login-tab").classList.toggle("active",!reg);$("#name-field").hidden=!reg;$("#auth-name").required=reg;$("#username-field").hidden=!reg;$("#auth-username").required=reg;$("#auth-username").disabled=!reg;$("#auth-title").textContent=t(reg?"register":"login");$("#auth-submit").textContent=t(reg?"register":"login");$("#auth-error").textContent=""}
function handleAccountLinks(){const p=new URLSearchParams(location.search);if(p.has("reset")){window.resetToken=p.get("reset");$("#reset-dialog").showModal()}}


async function loadAdminMembers(offset=memberOffset){memberOffset=Math.max(0,offset);const list=$("#members-list"),pager=$("#member-pagination");if(!list)return;const params=new URLSearchParams({q:$("#member-search")?.value.trim()||"",limit:"20",offset:String(memberOffset)});try{const d=await api(`/api/admin/users?${params}`);list.innerHTML=d.users.map(u=>`<div class="member-row"><button class="member-open" data-member-details="${u.id}"><b>${esc(u.display_name)}</b><span>@${esc(u.username)}${u.role==="moderator"?` · ${t("moderatorRole")}`:""}</span>${u.is_banned?`<i>${u.ban_until?`${t("bannedUntil")} ${date(u.ban_until)}`:t("banned")}</i>`:""}</button>${u.role!=="admin"?`${!u.is_banned?`<select class="ban-duration" aria-label="${t("banDuration")}"><option value="3600">${t("oneHour")}</option><option value="86400">${t("oneDay")}</option><option value="604800">${t("oneWeek")}</option><option value="0">${t("permanent")}</option></select>`:""}<button class="small-button" data-ban="${u.id}">${u.is_banned?t("unban"):t("ban")}</button>${me?.role==="admin"?`<button class="small-button" data-role-toggle="${u.id}" data-role="${u.role}">${u.role==="moderator"?t("removeModerator"):t("grantModerator")}</button>`:""}`:""}</div>`).join("")||`<p class="muted">${t("noMembers")}</p>`;const end=Math.min(memberOffset+20,d.total);pager.innerHTML=`<span>${memberOffset+1}–${end} / ${d.total}</span><button class="small-button" data-member-page="${Math.max(0,memberOffset-20)}" ${memberOffset===0?"disabled":""}>${t("previous")}</button><button class="small-button" data-member-page="${memberOffset+20}" ${end>=d.total?"disabled":""}>${t("next")}</button>`}catch(err){list.innerHTML=`<p class="muted">${esc(err.message)}</p>`}}
